import type { NextConfig } from "next";

// Leasing Intelligence demo pages: static exports in public/leasing/<client>/ (generated by
// magento/leasing_unicredit/export_static.py), one private link per client, password-gated in src/middleware.ts.
const LEASING_CLIENTS = "leanpay|unicredit|tbi";

const nextConfig: NextConfig = {
  async rewrites() {
    return [
      {
        source: `/leasing/:client(${LEASING_CLIENTS})`,
        destination: "/leasing/:client/index.html",
      },
    ];
  },
  async headers() {
    return [
      {
        source: "/leasing/:path*",
        headers: [
          { key: "X-Robots-Tag", value: "noindex, nofollow" },
          { key: "Cache-Control", value: "private, no-store" },
        ],
      },
    ];
  },
};

export default nextConfig;
